-- ---------------------------------------------------------------------------
-- Seed: section 1 of the course — generated by scripts/course/build-seed.mjs
-- from docs/course/section-1.yaml and scripts/course/fixtures/demo.yaml.
-- Do not edit by hand; regenerate.
--
-- Units 1–2 are published: they have lessons written. Their sentences are
-- hand-written and NOT yet reviewed by a native speaker. Units 3–24 go in as
-- drafts — outline, words and tips — for the pipeline to fill.
--
-- Idempotent: every row is an upsert on its deterministic id.
-- ---------------------------------------------------------------------------

-- Units are unique by (section, ordinal), so a unit inserted mid-section would
-- collide with the one it displaces. Park the ordinals first; the upsert below
-- sets every one back.
update public.units set ordinal = ordinal + 1000 where section_id = 1;

on conflict (id) do update set ordinal = excluded.ordinal, slug = excluded.slug, title_en = excluded.title_en, cefr = excluded.cefr, status = excluded.status;

on conflict (id) do update set section_id = excluded.section_id, ordinal = excluded.ordinal, slug = excluded.slug, title_en = excluded.title_en, summary_en = excluded.summary_en, grammar_focus = excluded.grammar_focus, register_max = excluded.register_max, status = excluded.status;

on conflict (id) do update set unit_id = excluded.unit_id, ordinal = excluded.ordinal, title_en = excluded.title_en, kind = excluded.kind, status = excluded.status;

on conflict (id) do update set unit_id = excluded.unit_id, title_en = excluded.title_en, body_md = excluded.body_md, status = excluded.status;

on conflict (id) do update set lemma = excluded.lemma, pos = excluded.pos, gloss_en = excluded.gloss_en, register = excluded.register, is_glue = excluded.is_glue, notes_en = excluded.notes_en, status = excluded.status;

on conflict (id) do update set lemma_id = excluded.lemma_id, form = excluded.form, features = excluded.features, gloss_en = excluded.gloss_en, unit_id = excluded.unit_id, audio_path = excluded.audio_path, status = excluded.status;

on conflict (id) do update set unit_id = excluded.unit_id, es = excluded.es, en = excluded.en, en_alt = excluded.en_alt, es_alt = excluded.es_alt, tokens = excluded.tokens, target_form_id = excluded.target_form_id, kind = excluded.kind, difficulty = excluded.difficulty, source = excluded.source, attribution = excluded.attribution, audio_path = excluded.audio_path, status = excluded.status;

on conflict (id) do update set lesson_id = excluded.lesson_id, ordinal = excluded.ordinal, kind = excluded.kind, form_id = excluded.form_id, sentence_id = excluded.sentence_id, tip_id = excluded.tip_id, mode = excluded.mode, review_count = excluded.review_count;
